extras = [p1_extra, p2_extra, p3_extra, p4_extra, p5_extra]

for i in range(5):
    for para in extras[i]:
        d["parts"][i]["say"].append(para)

words = [sum(len(s.split()) for s in p["say"]) for p in d["parts"]]
print("Updated Day 26 words per part:", words)
print("Total words:", sum(words))
assert all(w >= 580 for w in words), "A part has < 580 words!"
assert sum(words) >= 3000, "Total words < 3000!"

with open("scripts/iot_net_day26.json", "w", encoding="utf-8") as f:
    json.dump(d, f, indent=2, ensure_ascii=False)

print("Saved expanded scripts/iot_net_day26.json successfully.")
